	"settings.item.retry.maxRetries.option.5.label": "5 次重试",
	"settings.item.retry.maxRetries.option.10.label": "10 次重试",
	"settings.item.retry.maxDelayMs.label": "最大重试延迟",
	"settings.item.retry.maxDelayMs.description":
		"重试之间的最大等待时间（毫秒）。当提供方要求等待更久、且备用凭据或模型均失败时，请求会立即失败而非休眠等待（例如 Anthropic 的 3 小时限流窗口）。设为 0 则取消上限 —— 让会话按提供方声明的配额重置自动恢复。",
	"settings.item.retry.waitForUsageReset.label": "等待用量重置",
	"settings.item.retry.waitForUsageReset.description":
		"当提供方报告用量已达上限并给出重置时间（任意提供方的 5 小时或每周配额窗口）时，休眠等待至重置，而非在超过 retry.maxDelayMs 后立即失败。等待可中止（Esc），但也会阻塞子代理，因此无人值守运行时建议关闭。",
	"settings.item.retry.modelFallback.label": "重试模型回退",
	"settings.item.retry.modelFallback.description": "允许重试恢复流程切换到已配置的回退模型",
	"settings.item.retry.usageAwareFallback.label": "感知用量的回退",
	"settings.item.retry.usageAwareFallback.description":
		"使用可靠的 coding-plan 配额报告优先选择同提供商账户，然后选择已配置的回退模型，最后才触及硬性用量限制。普通配置的 API 密钥不参与。",
	"settings.item.retry.usageReservePct.label": "预留余量",
	"settings.item.retry.usageReservePct.description":
		"当剩余百分比低于此值时，将 coding-plan 模型视为接近上限。未知或无法映射的用量会继续使用主模型。",
	"settings.item.retry.usageReservePct.option.5.label": "5%",
	"settings.item.retry.usageReservePct.option.5.description": "仅在额度几乎耗尽时操作",
	"settings.item.retry.usageReservePct.option.10.label": "10%",
	"settings.item.retry.usageReservePct.option.10.description": "均衡的安全余量",
	"settings.item.retry.usageReservePct.option.15.label": "15%",
	"settings.item.retry.usageReservePct.option.15.description": "保守",
	"settings.item.retry.usageReservePct.option.20.label": "20%",
	"settings.item.retry.usageReservePct.option.20.description": "提前保护",
	"settings.item.retry.usageReservePct.option.25.label": "25%",
	"settings.item.retry.usageReservePct.option.25.description": "非常保守",
	"settings.item.retry.usageReservePolicy.label": "预留策略",
	"settings.item.retry.usageReservePolicy.description": "当所有同提供商 coding-plan 账户都进入预留余量时的处理方式。",
	"settings.item.retry.usageReservePolicy.option.confirm.label": "交互确认",
	"settings.item.retry.usageReservePolicy.option.confirm.description":
		"交互会话保持使用主模型直到确认；后台代理自动回退",
	"settings.item.retry.usageReservePolicy.option.auto.label": "自动回退",
	"settings.item.retry.usageReservePolicy.option.auto.description": "始终选择下一个符合条件的已配置回退模型",
	"settings.item.retry.usageReservePolicy.option.fail-closed.label": "安全失败",
	"settings.item.retry.usageReservePolicy.option.fail-closed.description": "不消耗预留配额，也不选择回退模型",
	"settings.item.retry.fallbackChains.label": "重试回退链",
	"settings.item.retry.fallbackChains.description":
		'将模型角色、模型选择器（"provider/model-id"）或提供方通配符（"provider/*"）映射到有序回退选择器的 JSON 对象，例如 {"default":["openai/gpt-4o-mini"],"google-antigravity/*":["google/*","google-vertex/*"]}。面向模型的键在该模型/提供方活跃时始终生效，与角色无关；"provider/*" 条目保留失败模型的 id 并替换提供方。带 id 前缀的通配符（"openrouter/google/*"）会为失败模型的裸 id 重新加前缀（google-antigravity/gemini-x -> openrouter/google/gemini-x），作为键使用时仅匹配该前缀下该提供方的 id。回退条目可带显式的思考后缀（"provider/model:low"、":high"、":max"、":off"）；裸条目继承失败回合的强度，而 "provider/*" 条目始终继承。',
	"settings.item.retry.fallbackRevertPolicy.label": "回退恢复策略",
	"settings.item.retry.fallbackRevertPolicy.description": "回退后何时返回主模型",
	"settings.item.retry.fallbackRevertPolicy.option.cooldown-expiry.label": "冷却期结束",
	"settings.item.retry.fallbackRevertPolicy.option.cooldown-expiry.description": "抑制窗口结束后返回主模型",
	"settings.item.retry.fallbackRevertPolicy.option.never.label": "永不",
	"settings.item.retry.fallbackRevertPolicy.option.never.description": "保持使用回退模型，直到手动切换",
	"settings.item.providers.anthropic.serverSideFallback.label": "Anthropic 服务端回退（Fable 5）",
	"settings.item.providers.anthropic.serverSideFallback.description":
		"当 Claude Fable 5 / Mythos 5 请求被 Anthropic 的安全分类器拦截时，在服务端改用 Claude Opus 5 重试（Anthropic `server-side-fallback-2026-06-01` beta）。需手动开启 —— 关闭则所有请求保持回退前的行为。",
	"settings.item.providers.ollama-cloud.maxConcurrency.label": "Ollama Cloud 最大并发数",
