	"settings.item.goal.enabled.label": "目标模式",
	"settings.item.goal.enabled.description": "启用按会话的目标模式和隐藏目标工具",
	"settings.item.goal.statusInFooter.label": "页脚显示目标状态",
	"settings.item.goal.statusInFooter.description": "在状态栏的目标指示器旁显示令牌预算",
	"settings.item.goal.continuationModes.label": "目标继续模式",
