	"settings.item.title.refreshOnReplan.label": "重新规划时刷新标题",
	"settings.item.title.refreshOnReplan.description": "待办初始化重新规划后刷新生成的会话标题，除非标题由用户设置",
	"settings.item.skills.registryUrl.label": "技能注册表",
