	"settings.item.commands.enableOpencodeUser.label": "OpenCode 用户命令",
	"settings.item.commands.enableOpencodeUser.description": "从 ~/.config/opencode/commands/ 加载命令",
	"settings.item.commands.enableOpencodeProject.label": "OpenCode 项目命令",
	"settings.item.commands.enableOpencodeProject.description": "从 .opencode/commands/ 加载命令",
	"settings.item.extensionHandlers.toolCallTimeoutMs.label": "工具调用处理器超时（毫秒）",
	"settings.item.extensionHandlers.toolCallTimeoutMs.description":
		"扩展 tool_call 处理器的有效工作超时时间，必须为有限正数；无效值使用 30000 毫秒，等待 OMP 自有对话框的时间不计入",
	"settings.item.exa.enabled.label": "Exa",
	"settings.item.exa.enabled.description": "启用 Exa 网页搜索提供方",
	"settings.item.exa.searchDelayMs.label": "Exa 搜索延迟",
	"settings.item.exa.searchDelayMs.description": "Exa 网页搜索请求之间的最小毫秒延迟；设为 0 可关闭节流",
	"settings.item.searxng.endpoint.label": "SearXNG 端点",
	"settings.item.searxng.endpoint.description": "用于网页搜索的自托管 SearXNG 实例基础 URL",
	"settings.item.browser.enabled.label": "浏览器",
	"settings.item.browser.enabled.description": "启用用于脚本化 Chromium 自动化（Puppeteer）的浏览器 eval 前奏",
	"settings.item.browser.cdpUrl.label": "浏览器 CDP URL",
	"settings.item.browser.cdpUrl.description":
		"默认 HTTP CDP 发现端点（例如 http://127.0.0.1:9222），用于连接现有浏览器而不是启动新浏览器。工具调用中显式指定的 app.cdp_url 或 app.path 优先。",
	"settings.item.browser.relay.label": "浏览器中继",
	"settings.item.browser.relay.description":
		"通过 omp 浏览器中继驱动你自己的 Chrome 标签页。安装一次扩展（`omp browser-relay install`）；浏览器前奏需要时中继服务器会自动启动。优先级高于 Browser CDP URL；设置 PI_BROWSER_RELAY=0 或 PI_BROWSER_RELAY=1 可覆盖。",
	"settings.item.browser.relayUrl.label": "浏览器中继 URL",
	"settings.item.browser.relayUrl.description": "omp 浏览器中继端点（默认 http://127.0.0.1:9224）。",
	"settings.item.browser.headless.label": "无头浏览器",
	"settings.item.browser.headless.description": "以无头模式启动浏览器（关闭后显示浏览器界面）",
	"settings.item.browser.cmux.label": "cmux 浏览器",
	"settings.item.browser.cmux.description":
		"cmux socket 可用时，使用 cmux WKWebView 界面进行浏览器自动化。可用 PI_BROWSER_CMUX=0 或 PI_BROWSER_CMUX=1 覆盖此设置。",
	"settings.item.browser.tern.label": "Tern 浏览器",
	"settings.item.browser.tern.description":
		"在 Tern 窗格内，将浏览器标签页作为画中画显示在 omp 窗格之上（原生网页视图），而非无头 Chromium；没有可承载它们的 Tern 窗口时回退为 Chromium。显式 app 选项、中继和 Browser CDP URL 优先；headed:false 或 app.tern:false 可使单次打开退出该模式。设置 PI_BROWSER_TERN=0 或 PI_BROWSER_TERN=1 可覆盖。",
	"settings.item.browser.freezeOnTurnEnd.label": "回合结束时冻结浏览器标签页",
	"settings.item.browser.freezeOnTurnEnd.description":
		"回合结束时冻结 OMP 拥有的无头浏览器标签页，使动画页面在空闲时不再消耗 CPU/GPU。标签页在下次使用时自动解冻；打开时传 persist:true 可使某个标签页免除冻结。",
	"settings.item.browser.idleCloseSec.label": "浏览器空闲关闭超时",
	"settings.item.browser.idleCloseSec.description":
		"关闭空闲超过这么多秒的 OMP 拥有的无头浏览器标签页和 Tern 浏览器画中画（0 = 从不；会话释放时仍会回收）。绝不触碰中继/CDP/派生的浏览器或其他会话的标签页。",
	"settings.item.browser.idleCloseSec.option.0.label": "永不",
	"settings.item.browser.idleCloseSec.option.900.label": "15 分钟",
	"settings.item.browser.idleCloseSec.option.1800.label": "30 分钟",
	"settings.item.browser.idleCloseSec.option.3600.label": "1 小时",
