	"slash.mcp.help.title": "MCP 服务器管理",
	"slash.mcp.help.description": "管理用于外部工具集成的 Model Context Protocol (MCP) 服务器。",
	"slash.mcp.help.commands": "命令：",
	"slash.mcp.help.commandsBody":
		"  /mcp add              添加新的 MCP 服务器（交互式向导）\n  /mcp add <name> [--scope project|user] [--url <url> --transport http|sse] [--token <token>] [-- <command...>]\n  /mcp list             列出所有已配置的 MCP 服务器\n  /mcp remove <name> [--scope project|user]    移除 MCP 服务器（默认：project）\n  /mcp test <name>      测试到 MCP 服务器的连接\n  /mcp reauth <name>    重新授权 MCP 服务器的 OAuth\n  /mcp unauth <name>    移除 MCP 服务器的 OAuth 认证\n  /mcp enable <name>    启用 MCP 服务器\n  /mcp disable <name>   禁用 MCP 服务器\n  /mcp smithery-search <keyword> [--scope project|user] [--limit <1-100>] [--semantic]\n                        搜索 Smithery 注册表并从选择器部署\n  /mcp smithery-login   登录 Smithery 并缓存 API key\n  /mcp smithery-logout  移除缓存的 Smithery API key\n  /mcp reconnect <name> 重新连接到指定 MCP 服务器\n  /mcp reload           强制重新加载并重新发现 MCP 运行时工具\n  /mcp resources        列出已连接服务器的可用资源\n  /mcp prompts          列出已连接服务器的可用提示\n  /mcp notifications    显示通知能力和订阅状态\n  /mcp help             显示此帮助信息",
